import{_ as o,c as e,o as r,ag as a}from"./chunks/framework.Cycwnjj0.js";const n="/assets/create-your-first-product-table.D473eh_V.webp",s="/assets/add-product-table-button.YqBpehrW.webp",c="/assets/create-new-product-table-popup-page.B6mpM_Y0.webp",u="/assets/save-changes-and-preview-button.DrNzjpMa.webp",p="/assets/preview-of-product-table.DpVpm_3L.webp",y=JSON.parse('{"title":"How to Create an Amazon Product Table With AzonPress","description":"","frontmatter":{},"headers":[],"relativePath":"guide/product-tables-module/how-to-create-an-amazon-product-table.md","filePath":"guide/product-tables-module/how-to-create-an-amazon-product-table.md"}'),i={name:"guide/product-tables-module/how-to-create-an-amazon-product-table.md"};function l(d,t,g,h,b,m){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="how-to-create-an-amazon-product-table-with-azonpress" tabindex="-1">How to Create an Amazon Product Table With AzonPress <a class="header-anchor" href="#how-to-create-an-amazon-product-table-with-azonpress" aria-label="Permalink to &quot;How to Create an Amazon Product Table With AzonPress&quot;">​</a></h1><p><strong>Product Table</strong> offers you showcasing the <strong>information</strong> of <strong>Amazon Products</strong> according to your needs through <strong>Tables</strong> and the most convenient is that you don&#39;t need to know any codes for creating your tables. This article will guide you through <strong>creating Product Table/s</strong> with AzonPress for <strong>Amazon products</strong> on your <strong>WordPress</strong> website.</p><h2 id="create-a-product-table" tabindex="-1">Create A Product Table <a class="header-anchor" href="#create-a-product-table" aria-label="Permalink to &quot;Create A Product Table&quot;">​</a></h2><p>To learn how to create a Product table with AzonPress, follow the steps with the screenshots below –</p><p>First, go to <strong>Amazon Products</strong> from the <strong>WordPress Sidebar</strong> or <strong>Product Tables</strong> from the <strong>Amazon</strong> dropdown in the top right corner of the <strong>AzonPress Navbar.</strong></p><p><strong>Remember</strong>, you need to <strong>connect</strong> your <strong>AzonPress</strong> with your <strong>Amazon Associate Account</strong> to get the <strong>Amazon dropdown</strong> option in the <strong>AzonPress Navbar</strong>.</p><p>Now, click on the <strong>Create Your First Product Table</strong> button.</p><p><img src="'+n+'" alt="Create your first Product table"></p><p>But, If you have already created product tables with AzonPress, you&#39;ll find the <strong>Add Product Table</strong> button to create a new table. Click on it and a pop-up page will appear.</p><p><img src="'+s+'" alt="Add Product Table button"></p><p>Give your table a <strong>Title</strong>. Now <strong>search</strong> for your desired <strong>products</strong> with <strong>keywords</strong> and a list of products will appear on the window.</p><p><strong>Remember</strong>, you need to <strong>connect</strong> your <strong>AzonPress</strong> with your <strong>Amazon Associate Account</strong> to fetch <strong>Amazon product data</strong>.</p><p>Now, select the ones you want to display, or can select all by clicking the <strong>Select All</strong> button. Finally, click on the <strong>Create Table</strong> button.</p><p><img src="'+c+'" alt="Create New Product Table popup page"></p><p>Now, you can see that a default product table has been created in your back end.</p><p>If you want to learn more about <strong>Customizing</strong> your <strong>Product Tables</strong>, read this <a href="/guide/product-tables-module/customization-of-product-tables.html">Documentation</a>. Also, to learn about <strong>Customizing</strong> tables through <strong>Appearance Settings</strong>, read this <a href="/guide/miscellaneous/appearance-settings.html">Documentation</a>.</p><p>Once you are done customizing the table, click the <strong>Save Changes</strong> button, and your table will be ready to display.</p><p>You can also see how your table will appear in your front end by clicking the <strong>Preview</strong> button.</p><p><img src="'+u+'" alt="Save changes and Preview button"></p><p>Here is a preview of what your table will look like in the front end.</p><p><img src="'+p+'" alt="Preview of Product table"></p><p>This is how you can create a product table efficiently using AzonPress!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',24)])])}const f=o(i,[["render",l]]);export{y as __pageData,f as default};
